/**
 * Optimized images live in /public/images (generated by `npm run images`).
 * Widths must match scripts/image-sources.json. Radio artwork slugs only ship a
 * 400x400 square crop (see artSrc).
 */
const WIDTHS: Record<string, number[]> = {
  'hero-fire': [640, 1280, 1920],
  'stage-red': [640, 1280, 1920],
  'crowd-red': [640, 1280, 1920],
  'pyro-stage': [640, 1280],
  fans: [640, 1280],
  'stage-amsterdam': [640, 1280],
  'festival-crowd': [640, 1280],
};

const base = import.meta.env.BASE_URL.replace(/\/$/, '');

export function imgSrc(slug: string, width?: number): string {
  const widths = WIDTHS[slug] ?? [640];
  const w = width && widths.includes(width) ? width : widths[widths.length - 1];
  return `${base}/images/${slug}-${w}.webp`;
}

export function imgSrcSet(slug: string): string {
  return (WIDTHS[slug] ?? [640]).map((w) => `${base}/images/${slug}-${w}.webp ${w}w`).join(', ');
}

export function artSrc(slug: string): string {
  return `${base}/images/${slug}-sq.webp`;
}
